import fs from 'fs';
import path from 'path';

/**
 * Load web-popularity blacklist hashes (generated by `src/cmd/gen-web-blacklist.ts`).
 *
 * A hash is blacklisted if it appears in ≥ threshold fraction of target websites
 * — interpret as "ubiquitous web noise not worth matching".
 *
 * Returns a flat Set<string>; the on-disk format is `{ [nodes]: string[] }`
 * but downstream code only needs a flat set.
 */
export function loadWebBlacklist(
  rootDir: string = process.cwd(),
  threshold = 0.6
): Set<string> {
  const cacheDirEnv = process.env['FP_CACHE_DIR'] ?? 'src/data/fingerprint-cache';
  const cacheDir = cacheDirEnv.startsWith('/') ? cacheDirEnv : path.join(rootDir, cacheDirEnv);
  const p = path.join(cacheDir, `web-blacklist-${threshold}.json`);
  if (!fs.existsSync(p)) {
    console.warn(`[web-blacklist] missing ${p} — returning empty set. Run: npx ts-node src/cmd/gen-web-blacklist.ts`);
    return new Set();
  }
  try {
    const raw = JSON.parse(fs.readFileSync(p, 'utf-8')) as Record<string, string[]>;
    const flat = new Set<string>();
    for (const arr of Object.values(raw)) for (const h of arr) flat.add(h);
    return flat;
  } catch (e) {
    console.warn(`[web-blacklist] failed to parse ${p}: ${(e as Error).message}`);
    return new Set();
  }
}

/**
 * Union two dup hash sets (e.g. CDN-based dup + web-popularity blacklist).
 */
export function unionSets(...sets: Array<Set<string> | undefined>): Set<string> {
  const out = new Set<string>();
  for (const s of sets) if (s) for (const h of s) out.add(h);
  return out;
}
